	1: {1.0, 0.875, 0.75, 0.625, 0.5, 0.375, 0.25, 0.125},
	2: {1.0, 0.9333333333333333, 0.8571428571428571, 0.7692307692307693, 0.6666666666666666, 0.5454545454545454, 0.4, 0.2222222222222222},
