			}
			// conv_transpose with rec_lo = [c, c] and rec_hi = [c, −c], the
			// two bands summed after.
			if 2*k < T {
				out[2*k*LatentChannels+c] = haar*xl + haar*xh
			}
			if 2*k+1 < T {
				out[(2*k+1)*LatentChannels+c] = haar*xl - haar*xh
			}
		}
	}
	return out
}

